package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.*; import com.primehr.shared.exception.IllegalLifecycleTransitionException; import jakarta.persistence.*; import org.hibernate.annotations.Nationalized; import java.time.*; import java.util.*;
@Entity @Table(name="rsp_evaluation_proceeding",uniqueConstraints=@UniqueConstraint(name="uk_rsp_evaluation_current_publication",columnNames={"agency_id","current_publication_key"}))
public class EvaluationProceeding extends RspAuditedEntity {
 public enum Status { DRAFT,OPEN,IN_ASSESSMENT,FOR_DELIBERATION,FINALIZED,CANCELLED }
 @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="vacancy_publication_id",nullable=false) private VacancyPublication publication; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="publication_policy_binding_id",nullable=false) private PublicationEvaluationPolicy binding; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="committee_id",nullable=false) private Committee committee; @Column(name="planned_as_of_date",nullable=false) private LocalDate plannedAsOfDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private Status status; @Column(name="candidate_set_revision",nullable=false) private int candidateSetRevision; @Column(name="execution_revision",nullable=false) private int executionRevision; @Column(name="current_publication_key",length=36) private String currentPublicationKey; @Nationalized @Column(name="vacancy_snapshot",nullable=false,length=32000) private String vacancySnapshot; @Nationalized @Column(name="policy_snapshot",nullable=false,length=32000) private String policySnapshot; @Nationalized @Column(name="committee_snapshot",nullable=false,length=32000) private String committeeSnapshot; @Column(name="vacancy_fingerprint",nullable=false,length=64) private String vacancyFingerprint; @Column(name="policy_fingerprint",nullable=false,length=64) private String policyFingerprint; @Column(name="committee_fingerprint",nullable=false,length=64) private String committeeFingerprint; @Column(name="opened_by",length=100) private String openedBy; @Column(name="opened_at") private Instant openedAt; @Column(name="cancelled_by",length=100) private String cancelledBy; @Column(name="cancelled_at") private Instant cancelledAt; @Nationalized @Column(name="cancellation_reason",length=2000) private String cancellationReason;
 protected EvaluationProceeding(){}
 public EvaluationProceeding(String agency,VacancyPublication publication,PublicationEvaluationPolicy binding,Committee committee,LocalDate planned,String vacancySnapshot,String policySnapshot,String committeeSnapshot,String vacancyFingerprint,String policyFingerprint,String committeeFingerprint){super(agency);this.publication=Objects.requireNonNull(publication);this.binding=Objects.requireNonNull(binding);this.committee=Objects.requireNonNull(committee);plannedAsOfDate=Objects.requireNonNull(planned);this.vacancySnapshot=requiredText(vacancySnapshot,"vacancySnapshot");this.policySnapshot=requiredText(policySnapshot,"policySnapshot");this.committeeSnapshot=requiredText(committeeSnapshot,"committeeSnapshot");this.vacancyFingerprint=requiredText(vacancyFingerprint,"vacancyFingerprint");this.policyFingerprint=requiredText(policyFingerprint,"policyFingerprint");this.committeeFingerprint=requiredText(committeeFingerprint,"committeeFingerprint");status=Status.DRAFT;currentPublicationKey=publication.getId();}
 public void open(String actor,Instant at){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Only a DRAFT proceeding may be opened");openedBy=requiredText(actor,"actor");openedAt=Objects.requireNonNull(at);status=Status.OPEN;}
 public void beginAssessment(){if(status!=Status.OPEN)throw new IllegalLifecycleTransitionException("Only an OPEN proceeding may begin assessment");status=Status.IN_ASSESSMENT;}
 public void beginDeliberation(){if(status!=Status.IN_ASSESSMENT)throw new IllegalLifecycleTransitionException("Only an IN_ASSESSMENT proceeding may enter deliberation");status=Status.FOR_DELIBERATION;}
 public void finalizeProceeding(){if(status!=Status.FOR_DELIBERATION)throw new IllegalLifecycleTransitionException("Only a FOR_DELIBERATION proceeding may be finalized");status=Status.FINALIZED;currentPublicationKey=null;}
 public void candidatesChanged(){requireDraft();candidateSetRevision++;}
 public void executionChanged(){if(status==Status.FINALIZED||status==Status.CANCELLED)throw new IllegalLifecycleTransitionException("A final proceeding is immutable");executionRevision++;}
 public void cancel(String actor,String reason,Instant at){if(status==Status.FINALIZED||status==Status.CANCELLED)throw new IllegalLifecycleTransitionException("A finalized or cancelled proceeding cannot be cancelled");String validatedActor=requiredText(actor,"actor");String validatedReason=requiredText(reason,"reason");Instant validatedAt=Objects.requireNonNull(at);cancelledBy=validatedActor;cancellationReason=validatedReason;cancelledAt=validatedAt;currentPublicationKey=null;status=Status.CANCELLED;}
 public void requireDraft(){if(status!=Status.DRAFT)throw new IllegalLifecycleTransitionException("Candidates may be admitted only while the proceeding is DRAFT");}
 public VacancyPublication getPublication(){return publication;} public PublicationEvaluationPolicy getBinding(){return binding;} public Committee getCommittee(){return committee;} public LocalDate getPlannedAsOfDate(){return plannedAsOfDate;} public Status getStatus(){return status;} public int getCandidateSetRevision(){return candidateSetRevision;} public int getExecutionRevision(){return executionRevision;} public String getVacancySnapshot(){return vacancySnapshot;} public String getPolicySnapshot(){return policySnapshot;} public String getCommitteeSnapshot(){return committeeSnapshot;} public String getVacancyFingerprint(){return vacancyFingerprint;} public String getPolicyFingerprint(){return policyFingerprint;} public String getCommitteeFingerprint(){return committeeFingerprint;} public String getOpenedBy(){return openedBy;} public Instant getOpenedAt(){return openedAt;} public String getCancelledBy(){return cancelledBy;} public Instant getCancelledAt(){return cancelledAt;} public String getCancellationReason(){return cancellationReason;}
}
